// Offline render of the same engine used by the AU/VST3. Input/output stereo f32.
#include "../Source/DelayEngine.h"
#include "../Source/Presets.h"
#include <fstream>
#include <iostream>
#include <string>
int main(int argc,char** argv){if(argc!=4)return 2;std::ifstream in(argv[1],std::ios::binary|std::ios::ate);if(!in)return 3;auto bytes=in.tellg();if(bytes<=0||bytes%8)return 4;std::vector<float> interleaved(size_t(bytes)/4);in.seekg(0);in.read(reinterpret_cast<char*>(interleaved.data()),bytes);if(!in)return 5;fm::Settings s;s.timeMs=142.85714f;s.feedback=.20f;s.mix=.15f;s.analog=.45f;s.duck=0;s.hp=60;s.lp=5000;s.width=1;s.diffusion=0;s.ping=false;s.mode=1;std::string recipe=argv[3];if(recipe=="analog"){s.mode=2;s.analog=.35f;s.feedback=.20f;s.lp=6000;}else if(recipe=="tape-diffuse"){s.diffusion=.015f;}else if(recipe=="studio-sixteenth")s=fm::presetSettings(fm::presets[35],105);else if(recipe=="full-vocal")s=fm::presetSettings(fm::presets[36],105);else if(recipe!="tape")return 6;fm::DelayEngine engine;engine.prepare(48000);float l[256],r[256];for(size_t offset=0;offset<interleaved.size()/2;offset+=256){int count=int(std::min(size_t(256),interleaved.size()/2-offset));for(int i=0;i<count;++i){l[i]=interleaved[2*(offset+i)];r[i]=interleaved[2*(offset+i)+1];}engine.process(l,r,count,s);for(int i=0;i<count;++i){if(!std::isfinite(l[i])||!std::isfinite(r[i]))return 7;interleaved[2*(offset+i)]=l[i];interleaved[2*(offset+i)+1]=r[i];}}std::ofstream out(argv[2],std::ios::binary);out.write(reinterpret_cast<const char*>(interleaved.data()),interleaved.size()*4);std::cout<<"Rendered "<<recipe<<" with current engine; Time142.85714ms Feedback"<<s.feedback<<" Mix"<<s.mix<<" Analog"<<s.analog<<" HP"<<s.hp<<" LP"<<s.lp<<" Diffusion"<<s.diffusion<<" Duck0 PingOff\n";return out?0:8;}
